55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/** Premiums round up — the MHPCO's favour. */
68	const roundPremium = (amount: number): number => Math.ceil(amount);
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const countByType = (items: Item[]): Map<string, number> => {
74	  const counts = new Map<string, number>();
75	  for (const item of items) {
76	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
77	  }
78	  return counts;
79	};
80	
81	/** A group of exactly 3 alike components is priced as one building block. */
82	const groupBasePremium = (type: string, count: number): number =>
83	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
84	
85	const LOYALTY_DISCOUNT_RATE = 0.2;
86	const LOYALTY_YEARS_THRESHOLD = 2;
87	const FOLLOWUP_DISCOUNT_RATE = 0.15;
88	
89	const CURSE_SURCHARGE_RATE = 0.5;
90	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
91	const HIGH_ENCHANTMENT_THRESHOLD = 5;
92	
93	/**
94	 * Rates are SUMMED here and multiplied by the base premium once by the caller,
95	 * so two modifiers on one item are additive (0.5 + 0.3) rather than
96	 * compounding (× 1.5 × 1.3) — per the spec's integration example.
97	 */
98	const itemSurchargeRate = (item: Item): number => {
99	  const curseRate = item.cursed ? CURSE_SURCHARGE_RATE : 0;
100	  const highEnchantmentRate =
101	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
102	      ? HIGH_ENCHANTMENT_SURCHARGE_RATE
103	      : 0;
104	  return curseRate + highEnchantmentRate;
105	};
106	
107	/**
108	 * Item-specific surcharges apply to the affected item's OWN base premium, so
109	 * they need a per-item pass — the grouping in `countByType` collapses both
110	 * `cursed` and `enchantment`.
111	 */
112	const itemSurcharges = (items: Item[]): number =>
113	  items.reduce(
114	    (sum, item) => sum + BASE_PREMIUMS[item.type] * itemSurchargeRate(item),
115	    0,
116	  );
117	
118	const quotePremium = (
119	  step: QuoteStep,
120	  customer: Customer,
121	  isFollowUpContract: boolean,
122	): number => {
123	  // Policy-scoped modifiers below are percentages of THIS total, never of a
124	  // running total — hence the explicit `policy` in the name: item surcharges
125	  // are percentages of each item's OWN base premium instead.
126	  const policyBasePremium = [...countByType(step.items)].reduce(
127	    (sum, [type, count]) => sum + groupBasePremium(type, count),
128	    0,
129	  );
130	  const firstInsuranceSurcharge =
131	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
132	  const loyaltyDiscount =
133	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
134	      ? policyBasePremium * LOYALTY_DISCOUNT_RATE
135	      : 0;
136	  const followUpDiscount = isFollowUpContract
137	    ? policyBasePremium * FOLLOWUP_DISCOUNT_RATE
138	    : 0;
139	
140	  return (
141	    policyBasePremium +
142	    itemSurcharges(step.items) +
143	    firstInsuranceSurcharge -
144	    loyaltyDiscount -
145	    followUpDiscount +
146	    PROCESSING_FEE
147	  );
148	};
149	
150	export const runScenario = (scenario: Scenario): ScenarioOutput => {
151	  const results = scenario.steps.map((step, index) => ({
152	    premium: roundPremium(
153	      quotePremium(step as QuoteStep, scenario.customer, index > 0),
154	    ),
155	  }));
156	
157	  return { results };
158	};
